$text=(Invoke-WebRequest -UseBasicParsing -Uri 'https://media.githubusercontent.com/media/cBioPortal/datahub/dca75cb3f32b82d54a6f78bf0a6323e5b975aca1/public/sarcoma_msk_2022/data_clinical_sample.txt').Content;if($text -is [byte[]]){$text=[Text.Encoding]::UTF8.GetString($text)};$c=@(($text -split '\r?\n'|Where-Object {$_ -and -not $_.StartsWith('#')})|ConvertFrom-Csv -Delimiter "`t");$m=(Invoke-WebRequest -UseBasicParsing -Uri 'https://raw.githubusercontent.com/trimcrae/Rare-cancers/da49c4e836533253825587f83656675dac4c913b/research/autonomy/data-opportunities-2026-09-30/deep-analysis/results/Foundation-complete-rearrangement-source-mapping.json').Content|ConvertFrom-Json;$sourceEMC=@($m.result.perEMC | ForEach-Object {'sarcoma_msk_2022-'+$_.sourceID}|Sort-Object);$exportEMC=@($c|Where-Object {$_.CANCER_TYPE_DETAILED -eq 'Extraskeletal Myxoid Chondrosarcoma'}|ForEach-Object {$_.SAMPLE_ID}|Sort-Object);[pscustomobject]@{clinicalEMCCount=$exportEMC.Count;EMCIdSetDifference=@(Compare-Object $sourceEMC $exportEMC).Count;matchedStatuses=@($c|Group-Object MATCHED_STATUS|Select-Object Name,Count);clinicalSHA256=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($text)))}|ConvertTo-Json -Depth 4
